old_string:
findByKeyword(text) {
  const normalized = String(text || '').trim().toLowerCase();
  const flows = this.list(true);
  return flows.find((f) => {
    const keywords = f.trigger_keyword.split(',').map((k) => k.trim().toLowerCase());
    return keywords.some((k) => k === normalized || normalized.startsWith(k));
  });
},

new_string:
findByKeyword(text) {
  const normalized = String(text || '')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .trim()
    .toLowerCase();
  const flows = this.list(true);
  return flows.find((f) => {
    const keywords = f.trigger_keyword.split(',').map((k) => k.trim().toLowerCase()).filter(Boolean);
    return keywords.some((k) => k === normalized || normalized.startsWith(`${k} `));
  });
},
